        .expect("write trace");
        fs::write(
            root.join("agent-turn-summary.json"),
            agent_turn_artifact_json("summary-task", false).to_string(),
        )
        .expect("write summary");
        fs::write(
            root.join("nodes")
                .join("child")
                .join("output")
                .join("agent-turn-trace.json"),
            agent_turn_artifact_json("nested-trace-task", false).to_string(),
        )
        .expect("write nested trace lookalike");
        fs::write(
            root.join("nodes")
                .join("child")
                .join("output")
                .join("agent-turn-summary.json"),
            agent_turn_artifact_json("nested-summary-task", true).to_string(),
        )
        .expect("write nested summary lookalike");

        let records = FsRunStore::new(&root)
            .load_record_set()
            .expect("load record set");
        let agent_turns = records
            .forest_input
            .passive_evidence
            .agent_turns
            .as_ref()
            .expect("agent-turn evidence");

        assert_eq!(agent_turns.summary.trace_file_count, 1);
        assert_eq!(agent_turns.summary.trace_parsed_count, 1);
        assert_eq!(agent_turns.summary.summary_file_count, 1);
        assert_eq!(agent_turns.summary.summary_parsed_count, 1);
        assert_eq!(agent_turns.summary.artifact_with_terminal_record_count, 2);
        assert_eq!(agent_turns.summary.artifact_with_final_message_count, 2);
        assert_eq!(agent_turns.summary.artifact_with_applied_patch_count, 1);
        assert_eq!(agent_turns.summary.tool_request_event_count, 2);
        assert_eq!(agent_turns.summary.tool_completed_event_count, 2);
        assert_eq!(agent_turns.summary.tool_failed_event_count, 2);

        let trace = agent_turns
            .traces
            .get("agent-turn-trace.json")
            .expect("trace artifact evidence");
        assert_eq!(trace.task_id, "trace-task");
        assert_eq!(trace.selected_model, "openai/gpt-5");
        assert!(trace.patch_applied);
        assert_eq!(trace.expected_file_change_count, 1);
        assert_eq!(trace.terminal_outcome.as_deref(), Some("completed"));

        let summary = agent_turns
            .summaries
            .get("agent-turn-summary.json")
            .expect("summary artifact evidence");
        assert_eq!(summary.task_id, "summary-task");
        assert!(!summary.patch_applied);
        assert_eq!(summary.llm_prompt_message_count, 1);
        assert!(summary.has_llm_response);
        assert!(
            !agent_turns
                .traces
                .contains_key("nodes/child/output/agent-turn-trace.json")
        );
        assert!(
            !agent_turns
                .summaries
                .contains_key("nodes/child/output/agent-turn-summary.json")
        );
        assert_eq!(records.agent_turn_records.traces.len(), 1);
        assert_eq!(records.agent_turn_records.summaries.len(), 1);
        assert!(
            !records
                .agent_turn_records
                .traces
                .contains_key("nodes/child/output/agent-turn-trace.json")
        );

        let graph = crate::Graph::from_records(&records);
        assert_eq!(graph.agent_turn_records().traces.len(), 1);

        let playback = crate::turn_event_steps_from_agent_turn_records(graph.agent_turn_records());
        let trace_steps = playback
            .iter()
            .filter(|step| step.artifact_path == "agent-turn-trace.json")
            .collect::<Vec<_>>();
        assert_eq!(trace_steps.len(), 4);
        assert_eq!(trace_steps[0].event_index, 0);
        assert_eq!(trace_steps[0].kind(), crate::TurnEventKind::ToolRequested);
        assert_eq!(trace_steps[0].tool_name(), Some("read_file"));
        assert_eq!(trace_steps[0].call_id(), Some("call-1"));
        assert_eq!(
            trace_steps[0]
                .response_tape_ref()
                .map(|response| response.assistant_message_id),
            Some("assistant-1")
        );
        assert_eq!(trace_steps[1].kind(), crate::TurnEventKind::ToolCompleted);
        assert_eq!(trace_steps[2].kind(), crate::TurnEventKind::ToolFailed);
        assert_eq!(trace_steps[3].kind(), crate::TurnEventKind::TurnFinished);
        assert_eq!(
            trace_steps[3].event_assistant_message_id(),
            Some("assistant-1")
        );
        let cursor = trace_steps[0].cursor();
        let resolved = crate::turn_event_step_at(graph.agent_turn_records(), &cursor)
            .expect("resolve playback cursor");
        assert_eq!(resolved.kind(), crate::TurnEventKind::ToolRequested);
        assert_eq!(resolved.tool_name(), Some("read_file"));
        assert_eq!(
            resolved
                .response_tape_ref()
                .map(|response| response.assistant_message_id),
            Some("assistant-1")
        );
        let ObservedTurnEventRecord::ToolRequested(request) = trace_steps[0].event else {
            panic!("expected first trace event to be the typed tool request");
        };
        assert_eq!(request.arguments.as_str(), "{\"file\":\"src/lib.rs\"}");

        fs::remove_dir_all(root).expect("remove temp run");
    }

